/// Resolves a wire error code (or canonical code) to its canonical dot-separated code.
pub fn canonical_for_wire(wire_code: &str) -> Option<&'static str> {
    let trimmed = wire_code.trim();
    if trimmed.is_empty() {
        return None;
    }
    for &canonical in ALL_CANONICAL_CODES {
        if canonical.eq_ignore_ascii_case(trimmed) {
            return Some(canonical);
        }
    }
    for &(alias, canonical) in WIRE_ALIAS_MAP {
        if alias.eq_ignore_ascii_case(trimmed) {
            return Some(canonical);
        }
    }
    None
}

/// Returns the primary wire-protocol alias for a canonical error code, if defined.
pub fn primary_wire_alias(canonical_code: &str) -> Option<&'static str> {
    let trimmed = canonical_code.trim();
    WIRE_ALIAS_MAP
        .iter()
        .find(|&&(_, canonical)| canonical == trimmed)
        .map(|&(alias, _)| alias)
}
